import{z as i,x as l,o,c as s,q as t,j as E,D as a,d as n,s as d,S as c}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"异常表","description":"","frontmatter":{"title":"异常表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/exception-table.md","filePath":"cs/exception-table.md","lastUpdated":1791413859000}'),B={name:"cs/exception-table.md"};function p(A,e,C,h,m,_){const r=l("Mermaid");return o(),s("div",null,[e[2]||(e[2]=t('<h1 id="异常表" tabindex="-1">异常表 <a class="header-anchor" href="#异常表" aria-label="Permalink to &quot;异常表&quot;">​</a></h1><div class="epigraph"><p>throw 不是 `goto` 到调用者源码：运行时用 PC 查表，找到落地垫与必须执行的清理，沿栈一帧帧展开，直到处理器匹配。</p><footer>—— 据 Itanium C++ ABI；DWARF 异常处理；Appel, Modern Compiler Implementation 整理</footer></div><p>上一课<a href="/cs/gc-mark-gen">标记清除与分代</a>把堆上的对象按可达性回收。<code>throw</code> 会拆掉一串还没返回的帧，那些帧上的栈对象要析构，堆对象仍须从还活着的根够到。本课不重写三色。缺口是<strong>落地信息</strong>：编译器为每段可能抛的代码发出 PC 区间 → 处理器/清理例程的表，而不是在每条边插显式跳转。组成课的<a href="/cs/exception-interrupt-entry">异常与中断入口</a>是硬件陷入；本课是语言运行时的展开。编译课到此结束，下一课进阶课从 lex 生成器起步；内核与用户态是操作系统课的第一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若用返回码把错误层层传，每层都要写。异常：动态找到最近的 <code>catch</code>。实现：不在热路径设「当前处理器」寄存器链表（也可，setjmp 风格），主流是表驱动：<code>.eh_frame</code> / LSDA 描述「PC 在这区间时，落地垫在那，要先跑哪些 cleanup」。展开：从当前帧的返回地址查表，执行析构与 finally，恢复上一帧 FP/SP/PC，重复。缺口是这份表，不是 <code>try</code> 语法。</p><p>精确 GC 与展开同时发生：展开中的栈仍是根；落地垫的栈图必须能枚举。本课点名合作，不把分代屏障再写一遍。</p><h3 id="表不是-isa-陷阱向量" tabindex="-1">表不是 ISA 陷阱向量 <a class="header-anchor" href="#表不是-isa-陷阱向量" aria-label="Permalink to &quot;表不是 ISA 陷阱向量&quot;">​</a></h3><p>缺页、非法指令进内核向量。<code>throw</code> 在用户态走运行时，通常不陷入，除非运行时主动 abort。不要把本课当特权级课。</p><p><span class="marginnote">Itanium C++ ABI 成为跨架构 unwinder 的事实描述。DWARF CFI 描述如何恢复寄存器。Appel 讨论异常作为非局部出口。零开销：未抛时 <code>try</code> 不写热路径，代价在表与抛时。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前端把 <code>try</code>/<code>catch</code>/<code>finally</code> 做成 AST。中端可当 CFG 额外边，或保持区域。后端：为区域发射落地垫代码，把 (beginPC, endPC, landingPad, action) 写入只读表。运行时提供 <code>__cxa_throw</code> 一类入口，查表展开。</p>',11)),(o(),E(c,null,{default:a(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TH%5B%22throw%22%5D%20--%3E%20TAB%5B%22PC%20%E6%9F%A5%E5%BC%82%E5%B8%B8%E8%A1%A8%22%5D%0A%20%20TAB%20--%3E%20CLN%5B%22cleanup%20%2F%20%E6%9E%90%E6%9E%84%22%5D%0A%20%20CLN%20--%3E%20LP%5B%22%E8%90%BD%E5%9C%B0%E5%9E%AB%20catch%22%5D%0A%20%20TAB%20--%3E%20UP%5B%22%E4%B8%8A%E4%B8%80%E5%B8%A7%E7%BB%A7%E7%BB%AD%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t('<p><span class="marginnote">术语翻译：「零开销异常」的意思是：不抛异常时，<code>try</code> 块在热路径上一条额外指令都不付——进 <code>try</code> 不保存寄存器，判断「谁接盘」的活全部推迟到真的 <code>throw</code> 那一刻，靠查那张 PC 区间表完成。代价被转移到抛的时候和二进制体积里。</span></p><p>无匹配处理器则 <code>terminate</code>。跨共享库展开要依赖同一 unwinder 约定，与 ABI 同类合同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>零开销模型：正常路径看不到异常寄存器。代价在代码体积与抛路径。setjmp/longjmp 模型在 <code>try</code> 时保存寄存器，热路径更重。本课主干表驱动。不要调度把「可能抛的调用」移过不能重排的副作用而不更新表区间。</p>',4)),(o(),E(c,null,{default:a(()=>[d(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22throw%20%E6%8A%9B%E5%87%BA%22%5D%20--%3E%20L%5B%22%E5%8F%96%E5%BD%93%E5%89%8D%E5%B8%A7%E8%BF%94%E5%9B%9E%E5%9C%B0%E5%9D%80%EF%BC%8C%E6%9F%A5%20LSDA%22%5D%0A%20%20L%20--%3E%20Q%7B%22%E6%9C%AC%E5%B8%A7%E6%9C%89%E5%8C%B9%E9%85%8D%E7%9A%84%20catch%EF%BC%9F%22%7D%0A%20%20Q%20--%20%22%E6%9C%89%22%20--%3E%20RUN%5B%22%E6%89%A7%E8%A1%8C%E6%B2%BF%E9%80%94%E6%89%80%E6%9C%89%E5%BE%85%E8%B7%91%E7%9A%84%E6%9E%90%E6%9E%84%E4%B8%8E%20finally%22%5D%0A%20%20RUN%20--%3E%20J%5B%22%E8%B7%B3%E8%BF%9B%E8%90%BD%E5%9C%B0%E5%9E%AB%EF%BC%8C%E8%BF%9B%E5%85%A5%20catch%22%5D%0A%20%20Q%20--%20%22%E6%B2%A1%E6%9C%89%22%20--%3E%20C2%5B%22%E4%BB%8D%E8%A6%81%E8%B7%91%E6%9C%AC%E5%B8%A7%E7%9A%84%E6%9E%90%E6%9E%84%E4%B8%8E%20finally%22%5D%0A%20%20C2%20--%3E%20P%5B%22%E6%81%A2%E5%A4%8D%E4%B8%8A%E4%B8%80%E5%B8%A7%20FP%2FSP%2FPC%EF%BC%8C%E5%90%91%E4%B8%8A%E8%B5%B0%E4%B8%80%E5%B8%A7%22%5D%0A%20%20P%20--%3E%20L%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<p><span class="marginnote">数字实例：三层调用 A 调 B 调 C，C 里 <code>throw</code> 而 A 才有 <code>catch</code>：展开器要逐帧查 3 次表、跑 B 和 C 两帧的析构，再跳进 A 的落地垫。若有人图省事在循环里靠抛异常报告「到末尾了」，一秒抛上百万次，查表加展开的开销立刻可见——异常不能当普通控制流用。</span></p><p>与 PIC：表里的地址常是相对的，以便文本滑动。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写内核信号与 <code>sigaction</code> 的叠放全文。不把 Windows SEH 抄成第二条主干。后课默认：语言异常靠用户态表展开，不能改页表。内核与用户态是操作系统课第一课：谁拥有机器、越过边界只能陷入。</p><p><span class="marginnote">常见误区：初学者把语言异常表当成 CPU 的中断向量表——那张表在内核、按异常号索引；本课的表在用户态、按 PC 区间索引，<code>throw</code> 通常根本不陷入内核。另一个误区是以为析构总会自动跑：线程被强杀或 <code>terminate</code> 时，栈可能根本不展开。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>异常表把 PC 区间映到落地垫与清理；抛时展开栈。</li><li>与硬件陷阱分家；与 GC 共享栈根枚举。</li><li>编译课收束；内核与用户态属于操作系统课。</li><li>出处：Itanium C++ ABI；DWARF；Appel。</li></ul>',7))])}const D=i(B,[["render",p]]);export{u as __pageData,D as default};
